-- Czech strain descriptions (strains.description_cs). Idempotent; run after the wave-2 migration.
update public.strains as s set description_cs = v.cs
from (values
  ('acapulco-gold', 'Mexická krajová sativa pojmenovaná podle zlatavého nádechu, který můžou palice dostat. Vysoká a vzdušná s dlouhým kvetením; daří se jí v teplém slunném podnebí a pod silným světlem uvnitř.'),
  ('ak-47', 'Hybrid z několika krajových linií – kolumbijské, mexické, thajské a afghánské. Dorůstá střední výšky s množstvím bočních větví a tvoří kompaktní, lepkavé palice. V pozdním kvetení silně voní.'),
  ('amnesia-haze', 'Oblíbenkyně holandských coffeeshopů s převahou Haze a citrusově zemitou vůní. Hodně vysoká a pomalu dozrává; hodí se pro pěstitele, kteří mají dost místa nad rostlinou a trpělivost.'),
  ('amnesia-haze-auto', 'Samonakvétací verze klasické Haze. Vyšší a pomalejší než většina autovek, od semínka často 11–12 týdnů. Zasaď ji rovnou do finálního květináče, ať se vyhneš stresu z přesazování.'),
  ('blue-dream', 'Kalifornské křížení Blueberry × Haze. Vysoká a bujná s dlouhými větvemi, které dobře reagují na zaštipování a SCROG. Sladká borůvková vůně; chce hodně světla a prostoru.'),
  ('blueberry', 'Indika s kořeny v 70. letech, postavená na thajských a afghánských liniích a ceněná pro borůvkovou vůni. Střední výška, ke konci kvetení často modré a fialové odstíny. Nenáročná a stabilní.'),
  ('blueberry-auto', 'Kompaktní autovka s ovocnou vůní Blueberry a častými fialovými odstíny. Obvykle hotová za 9–10 týdnů od semínka; dobrá volba na balkon a do malých stanů.'),
  ('bubba-kush', 'Silná indika se sladkou hašišovou vůní připomínající kávu. Zůstává nízká a zavalitá s mohutnými palicemi. Kvůli husté stavbě hlídej v pozdním kvetení vlhkost.'),
  ('cheese', 'Britský fenotyp Skunk #1, který proslavil kolektiv Exodus; jméno má podle výrazné, slané vůně. Snadno se pěstuje a dobře nese; pořádný uhlíkový filtr je nutnost.'),
  ('critical-mass', 'Afghani × Skunk #1 vyšlechtěná pro velmi těžké palice. Větve v pozdním kvetení často potřebují podepřít a husté palice chtějí dobré proudění vzduchu a nízkou vlhkost, jinak hrozí plíseň.'),
  ('durban-poison', 'Čistá jihoafrická krajová sativa se sladkou anýzovou vůní. Vysoká s velkými listy a velkými hlavičkami trichomů, na sativu nečekaně rychlá. Venku dobře snáší slunce.'),
  ('gelato', 'Sunset Sherbet × Thin Mint GSC ze San Francisca. Sladká dezertní vůně a barevné, husté palice. Střední výška a průměrná sklizeň; kvalitě pomůže pomalé sušení a zrání.'),
  ('girl-scout-cookies', 'OG Kush × Durban Poison ze San Francisca, často zkracovaná na GSC. Střední sklizeň hustých, ojíněných palic, které můžou za chladných nocí zfialovět. Prospívá jí odlistění a stálá vlhkost.'),
  ('gorilla-glue-4', 'Chem’s Sister × Sour Dubb × Chocolate Diesel, pojmenovaná podle extrémně lepkavé pryskyřice. Na začátku kvetení se hodně natahuje, takže plánuj výšku a trénuj včas. Těžké, mohutné palice s vůní nafty a borovice.'),
  ('gorilla-glue-auto', 'Genetika Gorilla Glue #4 s ruderalis pro automatické kvetení, obvykle 9–10 týdnů od semínka. Lepkavou pryskyřici originálu si drží v menší postavě.'),
  ('granddaddy-purple', 'Purple Urkle × Big Bud z Kalifornie, proslulá sytě fialovými palicemi a vůní hroznů a lesního ovoce. Kompaktní a mohutná; barvy nejlépe vyniknou s chladnějšími nocemi na konci kvetení.'),
  ('green-crack', 'Potomek Skunk #1 s ostrou mangovou vůní, někdy prodávaný jako Green Cush. Na sativu rychlá a vydatná uvnitř i venku; po přepnutí se natahuje středně.'),
  ('hindu-kush', 'Krajová indika z hor mezi Afghánistánem a Pákistánem, základ většiny linií Kush. Nízká, se širokými listy a odolná, s pryskyřičnou, zemitě sladkou vůní.'),
  ('jack-herer', 'Hybrid Haze × Northern Lights #5 × Shiva Skunk pojmenovaný po konopném aktivistovi. Vysoká, otevřená stavba s kořenitou borovicovou vůní. Fenotypy se liší, takže se vyplatí vybrat dobrou matku.'),
  ('lowryder', 'První široce dostupná autovka, postavená z Northern Lights #2, William’s Wonder a linie ruderalis. Drobné rostliny, které dozrají zhruba za 8–9 týdnů od semínka bez ohledu na světelný režim.'),
  ('northern-lights', 'Klasická indika s afghánskými kořeny, kompaktní a košatá s krátkými internodii. Odpouští začátečnické chyby, odolává škůdcům a spolehlivě dává husté, pryskyřičné palice. V malém stanu zůstane nízká.'),
  ('northern-lights-auto', 'Northern Lights zkřížená s ruderalis. Kompaktní a velmi vhodná pro začátečníky, obvykle hotová asi za 9–10 týdnů od semínka. Vyhni se silnému tréninku; nejlíp funguje jemné LST.'),
  ('og-kush', 'Základní kámen západního pobřeží, ze kterého vychází spousta moderních hybridů, se zemitou vůní borovice a citronu. Střední výška; ve vlhkých místnostech má sklon k padlí, takže udržuj proudění vzduchu a prosvětlené listy.'),
  ('purple-haze', 'Sativa z rodiny Haze, populární v 60. a 70. letech, s fialově nadechnutými palicemi a sladkou zemitou vůní. Vysoká a otevřená; fialová barva se víc ukáže při chladných nocích.'),
  ('purple-kush', 'Čistá indika z linií Hindu Kush a Purple Afghani. Nízké, široké rostliny s krátkými internodii a hustými, často fialovými květy. Dobrá volba pro pěstování s nízkým stropem.'),
  ('skunk-1', 'Jeden z prvních stabilizovaných hybridů (Afghani × Acapulco Gold × Colombian Gold), rodič nespočtu moderních odrůd. Vyrovnaná, bujná a rychlá, se silnou zemitou vůní, která si žádá dobrý uhlíkový filtr.'),
  ('sour-diesel', 'Klasika z východního pobřeží, dlouho dostupná jen jako řízek, s předky z Chemdog a ostrou vůní paliva. Vytáhlá a vysoká s dlouhým kvetením; trénink a trpělivost se vyplatí. Potřebuje silný filtr na pach.'),
  ('super-lemon-haze', 'Lemon Skunk × Super Silver Haze s jasnou citrusovou vůní. Po přepnutí se silně natahuje a ocení síť nebo tyčky. Palice jsou spíš dlouhé a ojíněné než husté.'),
  ('super-silver-haze', 'Skunk × Northern Lights × Haze, několikanásobná vítězka pohárů z konce 90. let. Vysoká s dlouhými, ojíněnými palicemi a citrusově kořenitou vůní. Potřebuje místo nad sebou a delší kvetení.'),
  ('trainwreck', 'Severokalifornská klasika mexického, thajského a afghánského původu s ostrou vůní citronu a borovice. Rychle roste a je vysoká; prospěje jí brzké zaštípnutí a podpůrná síť.'),
  ('wedding-cake', 'Triangle Kush × Animal Mints, prodávaná i jako Triangle Mints #23. Spíš indikového typu se sladkou vůní vanilky a těsta a spoustou pryskyřice. Dobře reaguje na zaštipování a vyrovnaný porost.'),
  ('white-rhino', 'Potomek White Widow s afghánskými a brazilskými kořeny. Nízká, vydatná a bohatá na pryskyřici; palice jsou tak husté, že pomůže podepřít větve a zajistit dobré proudění vzduchu.'),
  ('white-widow', 'Křížení brazilské sativy a jihoindické indiky z holandské scény 90. let, známé palicemi obalenými bílými trichomy. Střední výška, pevné větvení a snadné, předvídatelné kvetení.'),
  ('zkittlez', 'Grape Ape × Grapefruit s třetím, utajeným rodičem, známá bonbonově ovocnými terpeny. Středně velké, dobře zvládnutelné rostliny; terpeny vyniknou při chladném a pomalém sušení.')
) as v(slug, cs)
where s.slug = v.slug;
